 if p['sub']=='海派甜点':body=f'<ellipse cx="200" cy="270" rx="115" ry="32" fill="#f9f5e9" stroke="#b59a6c"/><path d="M120 181 Q200 146 280 181L269 253Q200 283 131 253Z" fill="{color}"/><ellipse cx="200" cy="181" rx="80" ry="24" fill="#e7cf9f"/><path d="M140 190L147 240M170 193L174 249M210 195L210 251M245 188L240 244" stroke="#ab784c" stroke-width="3"/>'
 if p['sub']=='文创与旅游伴手礼':body='<path d="M105 128L235 102L298 153L285 290L154 320L105 265Z" fill="#294438"/><path d="M105 128L158 178L298 153L235 102Z" fill="#b59a6c"/><path d="M158 178L154 320" stroke="#e8d4ae"/><text x="215" y="236" fill="#f3ede2" font-size="28" font-family="Georgia" text-anchor="middle">Qie.</text>'
 Path('public/images/'+i+'.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 380"><rect width="400" height="380" fill="{bg}"/><circle cx="200" cy="186" r="143" fill="none" stroke="#b59a6c" opacity=".35"/>{body}<text x="200" y="360" text-anchor="middle" fill="#625748" font-size="10" letter-spacing="3">CONCEPT ILLUSTRATION</text></svg>')
